                queue.add(activity);
            }
        }
        if (queue == null) {
            activity.run();
        }
        return null;
    });
    stub.when(bookieClient).forceLedger(any(BookieId.class), anyLong(), any(BookkeeperInternalCallbacks.ForceLedgerCallback.class), any());
}

