    final BookkeeperProtocol.GetBookieInfoRequest.Builder getBookieInfoBuilder = BookkeeperProtocol.GetBookieInfoRequest.newBuilder().setRequested(BookkeeperProtocol.GetBookieInfoRequest.Flags.FREE_DISK_SPACE_VALUE);
    final BookkeeperProtocol.Request getBookieInfoRequest = BookkeeperProtocol.Request.newBuilder().setHeader(headerBuilder).setGetBookieInfoRequest(getBookieInfoBuilder).build();
    GetBookieInfoProcessorV3 getBookieInfo = new GetBookieInfoProcessorV3(getBookieInfoRequest, requestHandler, requestProcessor);
    getBookieInfo.run();
    // get BookieInfo succeeded.
    verify(getBookieInfoStats, times(1)).registerSuccessfulEvent(anyLong(), eq(TimeUnit.NANOSECONDS));
    // get BookieInfo failed.
    when(requestProcessor.getBookie().getTotalFreeSpace()).thenThrow(new IOException("test for failed."));
    getBookieInfo.run();
    verify(getBookieInfoStats, times(1)).registerFailedEvent(anyLong(), eq(TimeUnit.NANOSECONDS));
}

