    underreplicationManager = mock(LedgerUnderreplicationManager.class);
    ledgerIndexer = mock(BookieLedgerIndexer.class);
    AuditorBookieCheckTask bookieCheckTask1 = new AuditorBookieCheckTask(conf, this.auditorStats, admin, ledgerManager, underreplicationManager, shutdownTaskHandler, ledgerIndexer, null, null);
