@Test(timeout = 60000)
public void testProcessNullResults() throws Exception {
    ZooKeeperClient zkc = mock(ZooKeeperClient.class);
    ZKTransaction transaction = new ZKTransaction(zkc);
    int numOps = 3;
    final CountDownLatch commitLatch = new CountDownLatch(numOps);
    final CountDownLatch abortLatch = new CountDownLatch(numOps);
    for (int i = 0; i < numOps; i++) {
        transaction.addOp(new CountDownZKOp(commitLatch, abortLatch));
    }
    transaction.processResult(KeeperException.Code.CONNECTIONLOSS.intValue(), "test-path", null, null);
    abortLatch.await();
    assertEquals(0, abortLatch.getCount());
    assertEquals(numOps, commitLatch.getCount());
}

@Test(timeout = 60000)
public void testAbortTransaction() throws Exception {
    ZooKeeperClient zkc = mock(ZooKeeperClient.class);
    ZKTransaction transaction = new ZKTransaction(zkc);
    int numOps = 3;
    final CountDownLatch commitLatch = new CountDownLatch(numOps);
    final CountDownLatch abortLatch = new CountDownLatch(numOps);
    for (int i = 0; i < numOps; i++) {
        transaction.addOp(new CountDownZKOp(commitLatch, abortLatch));
    }
    transaction.abort(new DLIllegalStateException("Illegal State"));
    abortLatch.await();
    assertEquals(0, abortLatch.getCount());
    assertEquals(numOps, commitLatch.getCount());
}

@Before
@Override
public void setup() throws Exception {
    super.setup();
    ensureURICreated(uri);
    localDir = testDir.newFolder("local");
    remoteDir = testDir.newFolder("remote");
    checkpointStore = new FSCheckpointManager(remoteDir);
    // initialize the scheduler
    realWriteExecutor = Executors.newSingleThreadExecutor(new ThreadFactoryBuilder().setNameFormat(THREAD_NAME_PREFIX + "%d").build());
    mockWriteExecutor = mock(ScheduledExecutorService.class);
    writeExecutorController = new MockExecutorController(realWriteExecutor).controlExecute(mockWriteExecutor).controlSubmit(mockWriteExecutor).controlSchedule(mockWriteExecutor).controlScheduleAtFixedRate(mockWriteExecutor, 5);
    checkpointExecutor = Executors.newSingleThreadScheduledExecutor();
    store = new RocksdbKVAsyncStore<>(() -> new RocksdbKVStore<>(), () -> namespace);
    FutureUtils.result(store.init(initSpec(runtime.getMethodName())));
}

@Test(timeout = 20000)
public void testRestoreBlockedSlow() throws Exception {
    final int numKvs = 100;
    TestStateStore testStore = Mockito.spy(new TestStateStore(runtime.getMethodName(), localDir, remoteDir, true, false));
    store.close();
    testStore.enableCheckpoints(true);
    testStore.setCheckpointRestoreIdleWait(Duration.ofSeconds(3));
    testStore.init();
    testStore.addNumKVs("transaction-1", numKvs, 0);
    // create base checkpoint
    String baseCheckpoint = testStore.checkpoint("checkpoint-1");
    testStore.close();
    String dbName = runtime.getMethodName();
    CheckpointInfo checkpoint = testStore.getLatestCheckpoint();
    CheckpointStore mockCheckpointStore = Mockito.spy(testStore.getCheckpointStore());
    File dbPath = localDir;
    List<CheckpointFile> files = CheckpointFile.list(testStore.getLocalCheckpointsDir(), checkpoint.getMetadata());
    String testFile = files.get(0).getRemotePath(dbName, checkpoint.getId(), true);
    // We wait for 10 sec for some data to show up. We will add the data after 8 sec. So the restore should succeed.
    Mockito.doReturn(getBlockedStream(testStore, testFile, Duration.ofSeconds(2))).when(mockCheckpointStore).openInputStream(testFile);
    Mockito.doReturn(mockCheckpointStore).when(testStore).newCheckpointStore();
    try {
        testStore.restore();
    } catch (Exception e) {
        fail("restore should succeed from slow stream");
    }
}

